('b-hub-telangana-biotech-hub', 'B-Hub Telangana (Biotech Hub)', 'incubator', 'Specialized biopharma scale-up center and contract development manufacturing hub.', 'B-Hub features a full-scale bioprocess pilot plant and cell line development suites supporting biopharmaceutical startups. The facility bridges the gap between laboratory R&D and commercial scale bio-manufacturing for vaccine and biologic startups.', 'https://bhub.telangana.gov.in', 'Hyderabad', 'Telangana', 'Accelerator', 'Govt of TG / BIRAC', '', '2021', 'Govt of Telangana & Telangana Life Sciences', 'BIRAC, Govt of TG Grants', 'Government Grant', 17.4398, 78.51241, '', 'live'),
('institute-of-bioresources-tbi-hyd', 'Institute of Bioresources TBI Hyd', 'incubator', 'Government incubator supporting bio-resource utilization, herbal formulation, and natural products.', 'Provides bio-extraction facilities, phytochemical testing labs, and regulatory compliance assistance for bio-product startups. The center promotes sustainable commercialization of medicinal plants and bio-inputs.', 'https://ibsd.gov.in', 'Hyderabad', 'Telangana', 'Incubator', 'DBT Govt of India / Bio-Resources', '', '2020', 'Department of Biotechnology (DBT)', 'DBT Govt of India', 'Government Funded', 17.37616, 78.53237, '', 'live'),
